UPDATE languages SET name_expression_id=(SELECT e.id FROM expressions e WHERE e.language_id=1818 AND e.text=languages.name_en LIMIT 1);
UPDATE language_locales SET name_expression_id=(SELECT e.id FROM expressions e WHERE e.language_id=1818 AND e.text=language_locales.name_en LIMIT 1);
UPDATE scripts SET name_expression_id=(SELECT e.id FROM expressions e WHERE e.language_id=1818 AND e.text=scripts.name_en LIMIT 1);
UPDATE regions SET name_expression_id=(SELECT e.id FROM expressions e WHERE e.language_id=1818 AND e.text=regions.name_en LIMIT 1);
